<script nonce="<?=e(csp_nonce())?>">(function(){document.querySelectorAll('.multi-select').forEach(function(box){const trigger=box.querySelector('.multi-select-trigger'),menu=box.querySelector('.multi-select-menu'),hidden=box.querySelector('input[type=hidden]');let options=JSON.parse(box.dataset.options||'[]'),selected=JSON.parse(box.dataset.selected||'[]');selected=selected.filter(Boolean);function sync(){hidden.value=selected.join(', ');trigger.textContent=selected.length?selected.join(', '):'Select '+(box.dataset.name==='tags'?'tags':'mistakes')+'...';let old=menu.querySelector('.multi-select-summary');if(old)old.remove();if(selected.length){const s=document.createElement('span');s.className='multi-select-summary';s.textContent=selected.length+' selected';menu.appendChild(s)}}function render(){menu.innerHTML='';options.forEach(function(option){const label=document.createElement('label');label.className='multi-select-option';const input=document.createElement('input');input.type='checkbox';input.value=option;input.checked=selected.includes(option);input.addEventListener('change',function(){if(input.checked&&!selected.includes(option))selected.push(option);if(!input.checked)selected=selected.filter(v=>v!==option);sync()});label.appendChild(input);label.appendChild(document.createTextNode(option));menu.appendChild(label)});const custom=document.createElement('div');custom.className='multi-select-custom';const input=document.createElement('input');input.type='text';input.placeholder='Add custom...';const add=document.createElement('button');add.type='button';add.textContent='Add';add.addEventListener('click',function(){const value=input.value.trim();if(value&&!selected.includes(value)){selected.push(value);if(!options.includes(value))options.push(value);render();sync()}input.value='';input.focus()});custom.appendChild(input);custom.appendChild(add);menu.appendChild(custom);sync()}trigger.addEventListener('click',function(e){e.stopPropagation();document.querySelectorAll('.multi-select.open').forEach(function(other){if(other!==box)other.classList.remove('open')});box.classList.toggle('open')});render()});document.addEventListener('click',function(){document.querySelectorAll('.multi-select.open').forEach(function(box){box.classList.remove('open')})})})();</script>